# One-Click Clean & Install Script for C:\Users\newbe\AIBot
$targetDir = "C:\Users\newbe\AIBot"
New-Item -ItemType Directory -Force -Path $targetDir | Out-Null
Set-Location $targetDir
Write-Host "Cleaning old cache, legacy scripts, and stale database..." -ForegroundColor Cyan
Remove-Item -Path "__pycache__" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "camfrog_boy.py", "bot.py", "monitor_bot.py", "setup_bot.py", "start_bot_test.py", "test_camfrog_connection.py", "get_camfrog_window.py" -Force -ErrorAction SilentlyContinue
Remove-Item -Path "data\camfrog_bot.db" -Force -ErrorAction SilentlyContinue
[System.IO.File]::WriteAllText((Join-Path $targetDir "config.py"), [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String("")))
Write-Host "Wrote config.py" -ForegroundColor Green
[System.IO.File]::WriteAllText((Join-Path $targetDir "ui_automation.py"), [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String("")))
Write-Host "Wrote ui_automation.py" -ForegroundColor Green
[System.IO.File]::WriteAllText((Join-Path $targetDir "camfrog_bot.py"), [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String("")))
Write-Host "Wrote camfrog_bot.py" -ForegroundColor Green
[System.IO.File]::WriteAllText((Join-Path $targetDir "room_monitor.py"), [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String("")))
Write-Host "Wrote room_monitor.py" -ForegroundColor Green
[System.IO.File]::WriteAllText((Join-Path $targetDir "room_data_processor.py"), [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String("")))
Write-Host "Wrote room_data_processor.py" -ForegroundColor Green
[System.IO.File]::WriteAllText((Join-Path $targetDir "test_bot.py"), [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String("")))
Write-Host "Wrote test_bot.py" -ForegroundColor Green
Write-Host "`nRunning unit tests (python test_bot.py)..." -ForegroundColor Cyan
python test_bot.py
Write-Host "`nAll 6 clean pipeline files are installed in C:\Users\newbe\AIBot!" -ForegroundColor Green